DOCS = {}
def D(mid, **kw): DOCS[mid] = kw

D("stat_anova1", intro="One-way analysis of variance compares the means of k independent groups with a single F test and follows a significant result with pairwise comparisons.",
  history="Introduced by R. A. Fisher in the 1920s for agricultural experiments; Welch (1951) added a test that does not require equal variances, and Tukey (1949) and Games and Howell (1976) added the pairwise procedures used here.",
  math=["Model: y_ij = μ + α_i + ε_ij, ε_ij ~ N(0, σ²), i = 1..k, j = 1..n_i, Σ n_i α_i = 0.", "SS_B = Σ n_i (ȳ_i − ȳ)², SS_W = Σ Σ (y_ij − ȳ_i)², N = Σ n_i.", "F = [SS_B / (k − 1)] / [SS_W / (N − k)] ~ F(k − 1, N − k) under H0: α_1 = … = α_k = 0.", "Welch: F_W = [Σ w_i (ȳ_i − ȳ_w)² / (k − 1)] / [1 + 2(k − 2)/(k² − 1) Σ (1 − w_i/W)² / (n_i − 1)], w_i = n_i / s_i², with df1 = k − 1 and df2 = (k² − 1) / [3 Σ (1 − w_i/W)² / (n_i − 1)].", "Effect sizes: η² = SS_B / SS_T, ω² = (SS_B − (k − 1) MS_W) / (SS_T + MS_W); confidence interval for η² by inverting the noncentral F distribution."],
  assumptions=["Independent observations within and between groups.", "Normally distributed errors (the F test is fairly robust with moderate n; see the robustness runs).", "Equal variances for the classical F test; Welch's test and Games-Howell comparisons do not need this."],
  algorithm=["Group means and variances → between and within sums of squares → F and p-value from the central F distribution.", "Welch ANOVA and Brown-Forsythe/Levene checks are computed alongside; Tukey HSD uses the studentised range distribution, Games-Howell uses Welch degrees of freedom with the studentised range."],
  limitations=["The normality check is a diagnostic, not a guarantee; heavy tails reduce power.", "Unbalanced designs with unequal variances inflate or deflate the classical F test: use the Welch result then (see robustness results)."],
  refs=["fisher25", "welch51", "tukey49", "gh76"],
  interp=["A small p-value says the group means are not all equal; it does not say which differ: read the pairwise table.", "η² is the share of total variance associated with the grouping; by convention 0.01, 0.06 and 0.14 are small, medium and large but context matters.", "If the Welch p-value and the classical p-value disagree, trust Welch when group variances differ."],
  bench=["scipy.stats.f_oneway (F and p), statsmodels (anova_lm, pairwise_tukeyhsd), pingouin (welch_anova, pairwise_gameshowell)."], bench_files=["A", "A2"])
D("stat_anova2", intro="Two-way ANOVA tests the effects of two crossed factors and their interaction on a continuous outcome, with Type II or Type III sums of squares for unbalanced data.",
  history="The factorial design and its analysis go back to Fisher's work at Rothamsted (Fisher 1925, 1935); the Type I/II/III terminology for unbalanced data was popularised by statistical packages in the 1970s.",
  math=["Model: y_ijk = μ + α_i + β_j + (αβ)_ij + ε_ijk, ε ~ N(0, σ²), with sum-to-zero (effect) coding.", "Type III SS of a term = SS_residual(model without the term) − SS_residual(full model), each term adjusted for all others; Type II adjusts for terms that do not contain it.", "F = (SS_term / df_term) / MS_residual ~ F(df_term, df_res).", "Partial η² = SS_term / (SS_term + SS_res), with a confidence interval from the noncentral F distribution."],
  assumptions=["Independent observations.", "Normal errors with constant variance across cells (Levene/Brown-Forsythe is reported).", "No empty cells when the interaction is included."],
  algorithm=["Nested least-squares fits with effect-coded design matrices; term SS by differences of residual SS; estimated marginal means as unweighted means of cell means."],
  limitations=["Main effects are hard to interpret when the interaction is large.", "Type III results depend on the coding; the engine fixes sum-to-zero coding, which is the convention that makes Type III meaningful."],
  refs=["fisher25", "fisher35"],
  interp=["Read the interaction first: if it is significant, describe effects of one factor at each level of the other.", "Partial η² is comparable across terms within one analysis."],
  bench=["statsmodels anova_lm with sum-to-zero contrasts (Types II and III), balanced and unbalanced data, and pingouin where it applies."], bench_files=["A", "A2"])
D("stat_rm_anova", intro="Repeated-measures ANOVA tests whether the mean outcome differs across conditions or time points measured on the same subjects, using the subject-by-condition interaction as the error term.",
  history="A development of the split-plot analysis of Fisher; Mauchly (1940) gave the sphericity test, and Greenhouse and Geisser (1959) and Huynh and Feldt (1976) gave the degree-of-freedom corrections used when sphericity fails.",
  math=["Model: y_ij = μ + π_i + τ_j + ε_ij with subject effects π_i and condition effects τ_j.", "F = [SS_cond / (k − 1)] / [SS_subj×cond / ((n − 1)(k − 1))] ~ F(k − 1, (n − 1)(k − 1)) under sphericity.", "Greenhouse-Geisser ε̂ = (tr S*)² / [(k − 1) tr(S*²)], where S* is the double-centred covariance matrix of the k measurements; corrected df = ε̂(k − 1) and ε̂(n − 1)(k − 1).", "Huynh-Feldt ε̃ = [n(k − 1)ε̂ − 2] / [(k − 1)(n − 1 − (k − 1)ε̂)], truncated at 1.", "Generalised η²_G = SS_cond / (SS_cond + SS_subj + SS_error)."],
  assumptions=["Each subject is measured under every condition (a complete balanced design; subjects with a missing condition are dropped and reported).", "Multivariate normality of the k measurements.", "Sphericity: equal variances of all pairwise differences (tested by Mauchly; the corrections relax it)."],
  algorithm=["Two-way decomposition of sums of squares by subject and condition; Mauchly's W on the orthonormal contrasts; ε corrections; Holm-adjusted paired t tests as follow-up."],
  limitations=["Only one within-subject factor and no between-subject factors; use the linear mixed model (E1) for more complex designs or unbalanced data.", "Mauchly's test has low power in small samples and is oversensitive in large ones, so the automatic correction rule is a convention, not a proof."],
  refs=["mauchly40", "gg59", "hf76"],
  interp=["Report the corrected p-value when ε̂ is well below 1 (a rule of thumb is below 0.75).", "Generalised η² allows comparison with between-subjects designs."],
  bench=["pingouin.rm_anova and pingouin.sphericity (F, corrected p, ε, Mauchly W)."], bench_files=["A", "A2"])
D("stat_ancova", intro="ANCOVA compares group means after adjusting for one or more continuous covariates, increasing precision and removing covariate imbalance.",
  history="Fisher introduced the analysis of covariance in the 1930s as a way to combine regression and ANOVA.",
  math=["Model: y_ij = μ + α_i + Σ β_k (x_kij − x̄_k) + ε_ij.", "Type III F test of the group effect: F = [(SSE_reduced − SSE_full) / (k − 1)] / [SSE_full / (N − k − p)].", "Adjusted mean of group i: ȳ_i − Σ β̂_k (x̄_ki − x̄_k); pairwise differences use the t distribution with the residual df and the standard error of a contrast of the fitted coefficients."],
  assumptions=["Linear relation between covariate and outcome, with the same slope in every group (homogeneity of regression slopes; tested and reported).", "Covariates measured without error and unaffected by the treatment.", "Independent normal errors with constant variance."],
  algorithm=["OLS with effect-coded groups plus covariates; hypothesis tests from nested fits; adjusted means from predictions at the covariate means; Holm-adjusted pairwise contrasts."],
  limitations=["A covariate that is itself affected by the grouping variable biases the adjusted difference.", "Non-parallel slopes make a single adjusted difference misleading."],
  refs=["fisher35"],
  interp=["The adjusted differences answer 'what would the group difference be at equal covariate values'.", "If the slope-homogeneity test rejects, report the interaction rather than the adjusted means."],
  bench=["statsmodels OLS/anova_lm (Type III) and pingouin.ancova."], bench_files=["A", "A2"])
D("stat_manova", intro="MANOVA tests whether group mean vectors of several continuous outcomes are equal, accounting for the correlation among the outcomes.",
  history="Wilks (1932) derived the likelihood-ratio criterion; Pillai (1955), Hotelling and Lawley contributed the alternative criteria; Rao (1951) gave the F approximation to Wilks' Λ.",
  math=["Model: Y = XB + E with rows of E ~ N_p(0, Σ).", "H = between-group SSP matrix, E = within-group SSP matrix; the statistics are functions of the eigenvalues λ_s of E⁻¹H.", "Wilks Λ = Π 1/(1 + λ_s); Pillai V = Σ λ_s/(1 + λ_s); Hotelling-Lawley U = Σ λ_s; Roy θ = λ_1/(1 + λ_1).", "Rao's F approximation for Λ: F = [(1 − Λ^(1/t)) / Λ^(1/t)] · [(df2) / (df1)], t = sqrt[(p²q² − 4)/(p² + q² − 5)], with df1 = pq and df2 = wt − pq/2 + 1."],
  assumptions=["Independent observations.", "Multivariate normality within groups.", "Equal covariance matrices across groups (Box's M is reported; it is sensitive to non-normality).", "More observations than responses within each group."],
  algorithm=["SSP matrices by least squares; eigenvalues of E⁻¹H by a symmetric reduction; the four statistics with their F approximations; follow-up univariate ANOVAs with Holm adjustment."],
  limitations=["Roy's largest root has only an upper-bound F approximation; it is reported as such.", "Wilks' Λ and Pillai's trace can disagree when assumptions fail; Pillai's trace is the more robust."],
  refs=["wilks32", "pillai55", "rao51"],
  interp=["A significant multivariate test says at least one outcome differs on some linear combination; the univariate follow-ups show where.", "Partial η² = 1 − Λ^(1/s) is the multivariate effect size."],
  bench=["statsmodels MANOVA (all four statistics, F, df, p) on the iris data."], bench_files=["A", "A2"])
D("stat_mancova", intro="MANCOVA extends MANOVA by adjusting the multivariate group comparison for continuous covariates.",
  history="A direct multivariate extension of Fisher's analysis of covariance; the test statistics are the same as for MANOVA.",
  math=["Model: Y = Zγ + Xβ + E, Z group indicators, X covariates, rows of E ~ N_p(0, Σ).", "H and E are the hypothesis and error SSP matrices from nested fits with and without the term; the four test statistics are functions of the eigenvalues of E⁻¹H, as in MANOVA.", "Each covariate also receives a multivariate test of its coefficient vector."],
  assumptions=["Those of MANOVA.", "Common regression slopes across groups for every response, and linearity of each response in the covariates."],
  algorithm=["Nested multivariate least squares; eigenvalue statistics for the group term and for each covariate."],
  limitations=["Slope homogeneity is only checked per covariate; with many covariates and few observations the error matrix may be ill conditioned (the engine reports its condition number and refuses singular cases)."],
  refs=["wilks32", "pillai55", "rao51"],
  interp=["The group test is adjusted for all covariates; compare it with the unadjusted MANOVA to see how much the covariates matter."],
  bench=["statsmodels multivariate OLS hypothesis tests (mv_test) with the same covariates."], bench_files=["A", "A2"])
D("stat_mann_whitney", intro="The Mann-Whitney U test compares two independent samples through their ranks and tests whether one tends to give larger values than the other.",
  history="Wilcoxon (1945) proposed the rank-sum form; Mann and Whitney (1947) gave the U form and the null distribution; Hodges and Lehmann (1963) supplied the associated location-shift estimator.",
  math=["U_1 = R_1 − n_1(n_1 + 1)/2, where R_1 is the rank sum of the first sample in the pooled data; U_2 = n_1 n_2 − U_1.", "Exact null distribution (no ties): P(U = u) = c(u; n_1, n_2) / C(n_1 + n_2, n_1), c from the Gaussian binomial coefficient.", "Normal approximation: z = (U − n_1n_2/2 ∓ 0.5) / σ_U with σ_U² = (n_1n_2/12) [(N + 1) − Σ(t³ − t)/(N(N − 1))] (tie-corrected).", "Rank-biserial correlation r = 1 − 2U_1/(n_1n_2) (sign follows the first group); Hodges-Lehmann shift = median of all n_1n_2 pairwise differences, with a confidence interval from order statistics of those differences."],
  assumptions=["Independent observations in two groups.", "An ordinal or continuous outcome.", "For the shift interpretation: the two distributions have the same shape. Without that, the test addresses P(X > Y) ≠ 1/2, not equality of medians."],
  algorithm=["Mid-ranks of the pooled sample; exact enumeration by counting when no ties and n small; otherwise the tie-corrected normal approximation with optional continuity correction."],
  limitations=["With unequal spreads the test is no longer a test of location and its Type I error for 'equal medians' can exceed the nominal level.", "The exact test is skipped when ties are present."],
  refs=["mann47", "wilcoxon45", "hl63"],
  interp=["The rank-biserial correlation is the effect size: 0 means no tendency, ±1 complete separation.", "A significant result means the probability that a draw from one group exceeds a draw from the other is not 1/2."],
  bench=["scipy.stats.mannwhitneyu (exact and asymptotic, three alternatives)."], bench_files=["B"])
D("stat_wilcoxon", intro="The Wilcoxon signed-rank test examines whether the median of paired differences (or of one sample) differs from a hypothesised value, using the ranks of the absolute differences.",
  history="Introduced by Wilcoxon (1945) in the same paper as the rank-sum test; the Pratt and split-zero conventions handle zero differences.",
  math=["d_i = x_i − y_i − μ0; drop or treat zeros by the chosen convention; r_i = rank of |d_i|.", "V = Σ_{d_i > 0} r_i; under H0 and symmetry E V = n(n + 1)/4, Var V = n(n + 1)(2n + 1)/24 − Σ(t³ − t)/48.", "Exact distribution of V by counting subsets of {1..n} (no ties); otherwise the normal approximation with continuity correction.", "Pseudomedian (Hodges-Lehmann) = median of the Walsh averages (d_i + d_j)/2, i ≤ j, with a confidence interval from their order statistics."],
  assumptions=["Paired differences (or the one sample) are independent.", "The distribution of the differences is symmetric about its median under H0.", "Continuous data for the exact p-value."],
  algorithm=["Zero handling (wilcox, pratt, zsplit), mid-ranks, exact counting distribution or tie-corrected normal approximation, Walsh-average interval."],
  limitations=["Asymmetric differences violate the null model: the test can reject for reasons other than a shift of the median (see the skewed scenario).", "Ties and zeros force the approximation."],
  refs=["wilcoxon45", "hl63"],
  interp=["The matched-pairs rank-biserial correlation is the effect size.", "The pseudomedian is the location estimate that goes with the test."],
  bench=["scipy.stats.wilcoxon (exact and approximate; wilcox, pratt and zsplit conventions; three alternatives)."], bench_files=["B"])
D("stat_kruskal", intro="The Kruskal-Wallis test compares three or more independent groups through the ranks of all observations; it is the rank analogue of one-way ANOVA.",
  history="Kruskal and Wallis (1952) extended the Mann-Whitney test to k groups; Dunn's procedure is the usual pairwise follow-up.",
  math=["H = [12 / (N(N + 1))] Σ R_i²/n_i − 3(N + 1), R_i = rank sum of group i.", "Tie correction: H_c = H / [1 − Σ(t³ − t)/(N³ − N)].", "Under H0, H_c is approximately χ²(k − 1).", "Effect sizes: ε² = H(N + 1)/(N² − 1) and η²_H = (H − k + 1)/(N − k). Dunn: z_ij = (R̄_i − R̄_j)/sqrt{[N(N + 1)/12 − Σ(t³ − t)/(12(N − 1))](1/n_i + 1/n_j)} with a multiplicity adjustment."],
  assumptions=["Independent observations within and between groups.", "Ordinal or continuous outcome.", "Same distribution shape in all groups for a location interpretation."],
  algorithm=["Pooled mid-ranks, H with the tie correction, chi-square p-value, Dunn comparisons with Holm, Bonferroni or Benjamini-Hochberg adjustment."],
  limitations=["The χ² approximation is poor when groups are very small.", "The omnibus test does not locate differences: use the Dunn table."],
  refs=["kw52"],
  interp=["A significant H says at least one group tends to give larger or smaller values than another.", "Use the Dunn table for pairs; its adjusted p-values control the family-wise error rate (Holm, Bonferroni) or the false discovery rate (Benjamini-Hochberg)."],
  bench=["scipy.stats.kruskal (H, p) and scikit-posthocs posthoc_dunn."], bench_files=["B"])
D("stat_friedman", intro="The Friedman test is the rank-based test for a difference among k related samples (a randomised complete block design), and Kendall's W measures the agreement between blocks.",
  history="Friedman (1937) proposed ranking within blocks to avoid the normality assumption of repeated-measures ANOVA.",
  math=["Within each block rank the k observations; R_j = rank sum of condition j over n blocks.", "χ²_F = [12 / (n k (k + 1))] Σ R_j² − 3n(k + 1), tie-corrected by 1 − Σ(t³ − t)/(n k (k² − 1)); χ²_F ≈ χ²(k − 1).", "Kendall's W = χ²_F / (n(k − 1)).", "Pairwise: Nemenyi (studentised range) and Conover (t on rank sums) with Holm adjustment."],
  assumptions=["Blocks (subjects) independent of each other.", "Observations within a block are ordinal or continuous and can be ranked.", "Complete blocks."],
  algorithm=["Within-block mid-ranks; the tie-corrected statistic; chi-square p-value; W; pairwise procedures."],
  limitations=["The χ² approximation is poor for very few blocks.", "The test uses only within-block information, so it is less powerful than a rank-ANOVA on aligned ranks in some designs."],
  refs=["friedman37"],
  interp=["W near 0 means no agreement among blocks about the ordering of conditions, W near 1 perfect agreement."],
  bench=["scipy.stats.friedmanchisquare and scikit-posthocs (Nemenyi, Conover) / pingouin.friedman."], bench_files=["B"])
D("stat_kendall", intro="Kendall's tau measures the monotone association of two variables through the numbers of concordant and discordant pairs, with an exact test for small samples and a tie-corrected version (tau-b).",
  history="Introduced by Kendall (1938).",
  math=["τ_a = (C − D) / [n(n − 1)/2]; τ_b = (C − D) / sqrt[(n0 − n1)(n0 − n2)], n0 = n(n − 1)/2, n1 = Σ t_i(t_i − 1)/2, n2 = Σ u_j(u_j − 1)/2.", "Exact null distribution of D (no ties) by Mahonian numbers (counting permutations by inversions).", "Normal approximation: z = (C − D) / sqrt Var, Var = [v0 − vt − vu]/18 + v1 + v2, with the usual tie terms.", "Approximate confidence interval for τ_b: tanh(atanh τ_b ± z sqrt(0.437/(n − 4))) (Fieller, Hartley and Pearson 1957); τ_a and τ_c (Stuart) are also reported."],
  assumptions=["Independent pairs of observations.", "Ordinal or continuous measurements.", "Monotone (not necessarily linear) association."],
  algorithm=["Pair counting in O(n²) with vectorised comparison; exact test when there are no ties and n is small; otherwise normal approximation; Spearman's ρ is reported for comparison."],
  limitations=["O(n²) time and memory limit very large n in the browser.", "tau-b and tau-a differ when ties are common; the engine reports tau-b."],
  refs=["kendall38"],
  interp=["τ is the difference between the probabilities of concordance and discordance for a random pair, so values are smaller in magnitude than Pearson r (for a bivariate normal, τ = (2/π) arcsin ρ)."],
  bench=["scipy.stats.kendalltau (tau-b, p-values) and scipy.stats.spearmanr."], bench_files=["B"])
D("stat_pca", intro="Principal component analysis finds orthogonal linear combinations of the variables that successively capture the largest variance, for dimension reduction and description.",
  history="Pearson (1901) and Hotelling (1933).",
  math=["Standardise to correlation form (or centre for covariance form): Z; S = Z'Z/(n − 1).", "Eigendecomposition S = V Λ V'; component scores = Z V; loadings = V Λ^{1/2} (correlations of variables with components for the correlation basis).", "Variance explained by component j: λ_j / Σ λ.", "Retention guides: Kaiser (λ > 1), broken-stick, and Horn's parallel analysis (95th percentile of eigenvalues of random normal data, simulated with the supplied seed)."],
  assumptions=["Continuous variables measured on comparable scales or standardised.", "Linear structure; no distributional assumption for the descriptive use."],
  algorithm=["Symmetric eigendecomposition (numpy eigh); sign convention making the largest absolute loading positive; Bartlett's sphericity and KMO as suitability checks."],
  limitations=["PCA is sensitive to outliers and to the choice of covariance or correlation basis.", "Principal components are not latent factors: use factor analysis for a measurement model."],
  refs=["hotelling33"],
  interp=["Loadings above about 0.4 in absolute value mark the variables that define a component; the scree plot and parallel analysis guide the number to keep."],
  bench=["numpy eigendecomposition of the correlation matrix and sklearn.decomposition.PCA (eigenvalues, loadings up to sign, scores)."], bench_files=["C", "C2"])
D("stat_efa", intro="Exploratory factor analysis models the correlations among observed variables by a smaller number of latent common factors, estimated by maximum likelihood, and rotates the solution for interpretation.",
  history="Spearman (1904) and Thurstone; Joreskog (1967) made maximum likelihood estimation practical; Kaiser (1958) proposed varimax.",
  math=["x = Λ f + ε, Var(f) = I (orthogonal) or Φ, Var(ε) = Ψ diagonal; Σ = ΛΛ' + Ψ.", "ML discrepancy: F(Λ, Ψ) = log|Σ| + tr(Σ⁻¹ R) − log|R| − p, minimised with respect to Ψ (Λ concentrated out by an eigen-decomposition of Ψ^{-1/2} R Ψ^{-1/2}).", "Likelihood-ratio test of exact fit: χ² = (n − 1 − (2p + 5)/6 − 2m/3) F̂ with df = [(p − m)² − (p + m)]/2.", "Rotations: varimax (orthogonal), promax (oblique, power 4 from the varimax solution), oblimin by gradient projection."],
  assumptions=["Continuous (approximately multivariate normal) data for the ML estimates and the χ² test.", "The number of factors is chosen beforehand; df ≥ 0 so the model is identified.", "Large enough sample (a common minimum is 5–10 observations per variable)."],
  algorithm=["L-BFGS-B on the uniquenesses with bounds [0.005, 1] and analytic gradient; Heywood cases (uniqueness at the lower bound) are flagged; rotation by iterative algorithms; Kaiser-Meyer-Olkin, Bartlett sphericity and parallel analysis as diagnostics."],
  limitations=["Heywood cases (uniqueness near 0) occur in small samples.", "Rotated solutions are unique only up to the rotation criterion chosen.", "Ordinal items would call for polychoric correlations, which are not implemented: Pearson correlations are used."],
  refs=["jor67", "kaiser58", "bj05"],
  interp=["Loadings show how strongly a variable reflects a factor; communality is the share of its variance explained by the common factors; the χ² test of exact fit is very demanding, so consult RMSEA as well."],
  bench=["Maximum-likelihood loadings and uniquenesses against statsmodels/sklearn factor analysis on simulated data and the rotation criteria against independent implementations (see the benchmark log)."], bench_files=["C", "C2"])
D("stat_cfa", intro="Confirmatory factor analysis tests a pre-specified measurement model in which each indicator loads on named latent factors, estimated by maximum likelihood on the covariance structure.",
  history="Joreskog (1969) generalised factor analysis to confirmatory, hypothesis-driven models; it underlies structural equation modelling.",
  math=["x = Λ ξ + δ, Σ(θ) = Λ Φ Λ' + Θ_δ, with a marker loading fixed at 1 (or factor variances fixed at 1) for identification.", "F_ML(θ) = log|Σ(θ)| + tr(S Σ(θ)⁻¹) − log|S| − p; χ² = (n − 1) F̂_ML with df = p(p + 1)/2 − q (q free parameters).", "Standard errors from the inverse of the information matrix (observed Hessian of the ML discrepancy); fit indices CFI, TLI, RMSEA (with CI) and SRMR."],
  assumptions=["Multivariate normality (the standard errors and χ² are not robust to its violation; the simulation shows the effect).", "A correctly specified, identified model: at least three indicators per factor, or two with correlated factors.", "Large sample size (a common minimum is 100–200)."],
  algorithm=["lavaan-style syntax parser; BFGS on the ML discrepancy with analytic gradient (restarted once if it stops early); Hessian-based standard errors; fit indices and the matrix of residual correlations as local-misfit diagnostics; Heywood (negative variance) cases flagged."],
  limitations=["Maximum-likelihood with normal theory only: no robust (Satorra-Bentler) or categorical estimators.", "Only measurement models: no regressions among latent variables."],
  refs=["jor69"],
  interp=["Judge fit by several indices together (CFI/TLI above about 0.95, RMSEA below about 0.06, SRMR below about 0.08 are conventional); standardised loadings are comparable across indicators."],
  bench=["semopy 2.x (loadings, standard errors, χ², fit indices) on the Holzinger-Swineford data."], bench_files=["C", "C2"])
D("stat_lda", intro="Linear discriminant analysis finds linear combinations of predictors that best separate known classes and classifies new observations with Gaussian class densities and a common covariance matrix.",
  history="Fisher (1936) derived the linear discriminant for the iris data.",
  math=["Within-class SSP W, between-class SSP B; discriminant directions are eigenvectors of W⁻¹B scaled to unit pooled within-class variance.", "Classification rule: assign x to class k maximising δ_k(x) = x'Σ⁻¹μ_k − ½ μ_k'Σ⁻¹μ_k + log π_k.", "Wilks' Λ tests of the discriminant functions use Bartlett's χ² approximation.", "Accuracy: resubstitution and leave-one-out cross-validation (closed form where feasible, otherwise 10-fold); Mardia skewness is reported as a normality diagnostic within classes."],
  assumptions=["Predictors multivariate normal within each class.", "Equal covariance matrices across classes.", "Independent observations; more observations than predictors."],
  algorithm=["Pooled covariance, symmetric eigenproblem for W⁻¹B, posterior class probabilities from the discriminant scores, leave-one-out cross-validation (10-fold when the closed form is not feasible)."],
  limitations=["Resubstitution accuracy is optimistic; use the cross-validated figure.", "Unequal covariance matrices call for quadratic discriminant analysis, which is not included."],
  refs=["fisher36"],
  interp=["Cross-validated accuracy should be compared with the accuracy of always guessing the majority class; structure coefficients show which predictors align with each function."],
  bench=["sklearn.discriminant_analysis.LinearDiscriminantAnalysis (scalings up to sign, predictions, posterior probabilities) and the iris data."], bench_files=["C", "C2"])
D("stat_cca", intro="Canonical correlation analysis finds paired linear combinations of two sets of variables with maximal correlation.",
  history="Hotelling (1936).",
  math=["With within-set covariance matrices S_xx, S_yy and cross-covariance S_xy, the squared canonical correlations ρ_k² are the eigenvalues of S_xx⁻¹ S_xy S_yy⁻¹ S_yx.", "Sequential Wilks' Λ_k = Π_{j ≥ k} (1 − ρ_j²); Bartlett χ² = −[n − 1 − (p + q + 1)/2] log Λ_k with df = (p − k + 1)(q − k + 1); Rao's F approximation as an alternative.", "Optional permutation test of the first canonical correlation (rows of one set permuted), with the Phipson-Smyth p-value."],
  assumptions=["Linear relations between the sets; multivariate normality for the Bartlett and Rao tests (the permutation test does not need it).", "More observations than the total number of variables."],
  algorithm=["Whitening of both sets followed by an SVD of the cross-covariance; standardised coefficients, structure correlations and redundancy indices."],
  limitations=["Estimates of the first canonical correlation are biased upward in small samples.", "Canonical weights are unstable under multicollinearity; read the structure correlations."],
  refs=["hotelling36"],
  interp=["The first canonical correlation is the largest correlation attainable between any linear combination of one set and any of the other; test pairs sequentially."],
  bench=["Direct SVD solution, sklearn.cross_decomposition.CCA (canonical correlations) and statsmodels CanCorr on the Linnerud data."], bench_files=["C", "C2"])
D("stat_ca", intro="Correspondence analysis represents the rows and columns of a contingency table as points in a low-dimensional space that displays the pattern of association.",
  history="Developed in the French school (Benzecri) from earlier work of Hirschfeld and Fisher; see Greenacre (1984).",
  math=["P = N/n, row masses r, column masses c; standardised residuals S = D_r^{-1/2}(P − rc')D_c^{-1/2}.", "SVD S = U Γ V'; principal row coordinates F = D_r^{-1/2} U Γ, column coordinates G = D_c^{-1/2} V Γ.", "Total inertia = Σ γ_k² = χ²/n (Pearson χ²), tested against χ²((I − 1)(J − 1)).", "Contribution of a row to a dimension: r_i F_ik²/γ_k²; quality cos²_ik = F_ik²/Σ_k F_ik²."],
  assumptions=["A table of non-negative counts; independent observations for the χ² test of independence.", "Expected counts large enough for the χ² approximation."],
  algorithm=["SVD of the standardised residual matrix; coordinates, contributions, qualities and Cramer's V."],
  limitations=["The χ² test needs adequate expected counts; the plot is descriptive.", "Distances between row points and column points are not directly comparable in the symmetric map."],
  refs=["greenacre84"],
  interp=["Points close together have similar profiles; the dimension's share of inertia says how much of the association the map displays."],
  bench=["Direct SVD, the χ² test from scipy.stats.chi2_contingency and the Caithness data (inertia and coordinates against published values)."], bench_files=["C", "C2"])
D("stat_km", intro="The Kaplan-Meier estimator gives a nonparametric estimate of the survival function from right-censored data, and weighted log-rank tests compare survival curves between groups.",
  history="Kaplan and Meier (1958).",
  math=["Ŝ(t) = Π_{t_i ≤ t} (1 − d_i/n_i), d_i events and n_i at risk at time t_i.", "Greenwood variance: Var Ŝ(t) = Ŝ(t)² Σ d_i/[n_i(n_i − d_i)].", "Confidence intervals by the log-log (default), log or plain transformation.", "Weighted log-rank: Z = Σ w_i (d_1i − E_1i) / sqrt Σ w_i² V_i with w_i = 1 (log-rank), n_i (Gehan-Breslow) or Peto-Peto S̃(t_i); χ² with k − 1 df for k groups.", "Restricted mean survival time = ∫_0^τ Ŝ(t) dt with standard error from the Greenwood-type variance."],
  assumptions=["Censoring is independent of the event time (non-informative).", "Subjects are independent.", "For the log-rank test, proportional hazards makes it most powerful; the Gehan and Peto-Peto weights are less sensitive to late differences."],
  algorithm=["Sorting and risk-set counting in a single pass; vectorised group-wise estimators; hypergeometric variance in the log-rank test."],
  limitations=["Median survival is undefined when the curve does not fall to 0.5.", "Tail estimates with few at risk are unstable."],
  refs=["km58"],
  interp=["Read the curve and its confidence band together; the median and the restricted mean summarise it; the log-rank p-value tests equality of the whole curves."],
  bench=["lifelines KaplanMeierFitter (survival, Greenwood CI), multivariate_logrank_test (log-rank, Gehan, Peto-Peto weights)."], bench_files=["D", "D2"])
D("stat_cox", intro="The Cox proportional hazards model relates covariates to the hazard of an event without specifying the baseline hazard.",
  history="Cox (1972); Efron (1977) gave the tie approximation used by default; Grambsch and Therneau (1994) the test of proportional hazards.",
  math=["h(t | x) = h_0(t) exp(x'β).", "Partial likelihood (Breslow ties): L(β) = Π_i [exp(x_i'β) / Σ_{j ∈ R(t_i)} exp(x_j'β)]^{δ_i}; Efron's version replaces the risk-set denominator for tied events by Σ_{R} − ((l − 1)/d) Σ_{tied}.", "Newton-Raphson on the log partial likelihood with step-halving; SE = sqrt diag(I(β̂)⁻¹); Wald, score and likelihood-ratio tests.", "Harrell's C; Breslow baseline cumulative hazard; scaled Schoenfeld residuals for the proportional hazards test."],
  assumptions=["Proportional hazards (tested).", "Non-informative censoring.", "Log-linear effect of continuous covariates.", "Independent subjects."],
  algorithm=["Sorted risk sets with cumulative sums for O(n) evaluation of the gradient and information; Efron or Breslow ties; step-halving; convergence on the relative change in log-likelihood and gradient."],
  limitations=["Time-varying covariates and strata are not supported.", "Perfect separation (a covariate that predicts events exactly) makes the estimate diverge; the engine detects non-convergence and reports it."],
  refs=["cox72", "efron77", "gt94"],
  interp=["exp(β) is a hazard ratio: 1.5 means a 50% higher instantaneous event rate per unit of the covariate, at every time.", "A significant Schoenfeld test indicates a time-varying effect."],
  bench=["lifelines CoxPHFitter (coefficients, SE, partial log-likelihood, C-index; Efron and Breslow) and statsmodels PHReg."], bench_files=["D", "D2"])
D("stat_aft", intro="Accelerated failure time models relate covariates to the logarithm of survival time: a covariate multiplies the time scale rather than the hazard.",
  history="Standard parametric survival regression (Kalbfleisch and Prentice 1980); the Weibull model has both a proportional-hazards and an AFT form.",
  math=["log T = x'β + σ W, with W the standardised error: extreme-value (Weibull), normal (log-normal), logistic (log-logistic), or extreme-value with σ = 1 (exponential).", "Log-likelihood: Σ δ_i [log f_W(w_i) − log σ] + (1 − δ_i) log S_W(w_i), w_i = (log t_i − x_i'β)/σ.", "Maximised by BFGS from several starts and polished by Newton steps with analytic gradient; SE from the numerical Hessian; time ratio = exp(β)."],
  assumptions=["The chosen error distribution is correct.", "Non-informative censoring.", "Covariates act multiplicatively on survival time."],
  algorithm=["Log-σ parameterisation to enforce positivity; analytic gradient; numerical Hessian for the covariance matrix; likelihood-ratio test against the intercept-only model."],
  limitations=["Coefficients are not comparable across distributions with different error laws.", "A wrong error distribution biases the estimates (see the misspecification run)."],
  refs=["kp80"],
  interp=["exp(β) is a time ratio: 1.3 means survival times are 30% longer per unit of the covariate."],
  bench=["lifelines WeibullAFTFitter, LogNormalAFTFitter and LogLogisticAFTFitter (log-likelihoods, coefficients)."], bench_files=["D", "D2"])
D("stat_finegray", intro="The Fine-Gray model regresses the subdistribution hazard of one cause of failure in the presence of competing risks, so that covariate effects translate into effects on the cumulative incidence.",
  history="Fine and Gray (1999); the cumulative incidence estimator is the Aalen-Johansen estimator.",
  math=["Subdistribution hazard: λ_1(t | x) = λ_10(t) exp(x'β), with the risk set containing subjects who have failed from a competing cause, weighted by w_i(t) = Ĝ(t)/Ĝ(min(T_i, t)), Ĝ the Kaplan-Meier estimate of the censoring distribution.", "Weighted partial likelihood with Breslow-type denominators; Newton-Raphson.", "Cumulative incidence F_1(t | x) = 1 − exp{−Λ_10(t) exp(x'β)}; the Aalen-Johansen estimator gives the nonparametric benchmark."],
  assumptions=["Independent censoring (possibly depending on covariates is not supported).", "Proportional subdistribution hazards.", "Event types correctly coded; one competing cause group."],
  algorithm=["IPCW weights constructed as a matrix over event times; weighted partial likelihood maximised by Newton-Raphson; Breslow baseline."],
  limitations=["The standard errors treat the censoring weights as known, so they omit the variance from estimating the censoring distribution (the simulation shows the effect on coverage). This is a known simplification: the result should be called a partially validated implementation.", "Time-varying covariates and several competing groups are not supported."],
  refs=["fg99", "aj78"],
  interp=["exp(β) is a subdistribution hazard ratio: it describes the effect on the cumulative incidence of the cause, not on the cause-specific hazard."],
  bench=["With no competing events the model coincides with the Cox model (checked to 2e-11); the cumulative incidence against an independent Aalen-Johansen calculation; coverage by simulation. No R cmprsk comparison was possible in this environment."], bench_files=["D", "D2"])
D("stat_parametric", intro="Parametric survival models fit exponential, Weibull, log-normal and log-logistic distributions to censored data and compare them by information criteria and against the Kaplan-Meier curve.",
  history="Classical parametric survival analysis (Kalbfleisch and Prentice 1980).",
  math=["The same accelerated-failure-time likelihood as the AFT model, estimated separately for each distribution.", "AIC = −2ℓ + 2k, BIC = −2ℓ + k log(n_events); Akaike weights w_m = exp(−Δ_m/2)/Σ exp(−Δ/2).", "Fitted survival is compared with Kaplan-Meier through the maximum absolute and root-mean-square differences."],
  assumptions=["One of the candidate distributions is adequate.", "Non-informative censoring."],
  algorithm=["Four AFT fits, information criteria, quantile tables and distance to the Kaplan-Meier curve."],
  limitations=["Choosing by AIC does not prove the chosen distribution is right; with small samples AIC often picks the wrong family (see the selection-frequency runs)."],
  refs=["kp80"],
  interp=["Prefer the lowest AIC but check the distance to the Kaplan-Meier curve and the plot of fitted and empirical survival."],
  bench=["lifelines parametric fitters (log-likelihood and parameters) for each distribution."], bench_files=["D", "D2"])
D("stat_lmm", intro="The linear mixed-effects model analyses clustered or longitudinal continuous data with fixed effects for the population and random effects for clusters.",
  history="Laird and Ware (1982); REML from Patterson and Thompson (1971); Satterthwaite (1946) approximate degrees of freedom.",
  math=["y_i = X_i β + Z_i b_i + ε_i, b_i ~ N(0, G(θ)), ε_i ~ N(0, σ² I).", "Profiled REML criterion over the relative covariance factor θ: −2ℓ_R = log|V| + log|X'V⁻¹X| + (n − p) log(r²) + …, with β̂ and σ̂² profiled out.", "β̂ = (X'V⁻¹X)⁻¹ X'V⁻¹ y, Cov β̂ = (X'V⁻¹X)⁻¹; Satterthwaite df from the numerical Hessian of the REML criterion.", "BLUPs b̂_i = G Z_i' V_i⁻¹ (y_i − X_i β̂); marginal and conditional R² (Nakagawa-Schielzeth)."],
  assumptions=["Normal random effects and errors.", "Correct specification of the random-effects structure.", "Independence of clusters; missingness ignorable (missing at random)."],
  algorithm=["Cluster-wise cross-products, a Cholesky parameterisation of the covariance, Nelder-Mead and L-BFGS-B from several starts on the profiled criterion; singular fits flagged."],
  limitations=["Only one grouping factor (no crossed or nested random effects).", "Kenward-Roger df are not implemented: Satterthwaite is used.", "With few clusters the REML variance components are biased and boundary estimates occur."],
  refs=["lw82", "sat46", "bates15", "ns13"],
  interp=["The intraclass correlation (random-intercept variance share) tells how strongly observations cluster; fixed-effect t tests use Satterthwaite df."],
  bench=["statsmodels MixedLM, and the published lme4 sleepstudy fit (variance components, fixed-effect SE, df, REML criterion)."], bench_files=["E1", "E2", "E3"])
D("stat_glmm", intro="The generalised linear mixed model extends the LMM to binary and count outcomes with a random intercept for each cluster.",
  history="Breslow and Clayton (1993) popularised approximate inference; adaptive Gauss-Hermite quadrature (Liu and Pierce 1994) gives accurate marginal likelihoods for one random effect.",
  math=["g(μ_ij) = x_ij'β + b_i, b_i ~ N(0, σ_b²); y_ij | b_i from a binomial or Poisson family.", "Marginal likelihood: L = Π_i ∫ Π_j f(y_ij | b) φ(b; 0, σ_b²) db, approximated by adaptive Gauss-Hermite quadrature with q nodes (q = 1 is the Laplace approximation).", "Maximisation over (β, log σ_b) by quasi-Newton; Wald tests from the numerical Hessian; likelihood-ratio test of σ_b = 0 uses the 50:50 mixture of χ²(0) and χ²(1)."],
  assumptions=["Normally distributed random intercepts.", "Correct link and family; independence given the random effect."],
  algorithm=["Vectorised adaptive quadrature per cluster (mode and curvature found by Newton iterations), BFGS on the marginal log-likelihood."],
  limitations=["Random intercepts only; no random slopes.", "The coefficients are cluster-conditional (not population-averaged): use GEE for the latter.", "No overdispersion model for the Poisson family; the validation is against an independent brute-force quadrature and published lme4 values, with no direct R run."],
  refs=["bc93", "lp94", "bates15"],
  interp=["exp(β) is a cluster-specific odds ratio (binomial) or rate ratio (Poisson); the latent intraclass correlation is σ_b²/(σ_b² + π²/3) for the logit link."],
  bench=["An independent brute-force quadrature MLE for the cbpp data and published lme4 estimates (Laplace); no GLMM reference in the Python packages used for the other methods."], bench_files=["E1", "E2", "E3"])
D("stat_gee", intro="Generalised estimating equations estimate population-averaged regression effects for clustered or longitudinal data with robust standard errors that remain valid when the working correlation is misspecified.",
  history="Liang and Zeger (1986); Pan (2001) gave the QIC for working-correlation selection.",
  math=["Estimating equation: Σ_i D_i' V_i⁻¹ (y_i − μ_i) = 0, V_i = φ A_i^{1/2} R(α) A_i^{1/2}.", "Robust (sandwich) covariance: B⁻¹ M B⁻¹ with B = Σ D'V⁻¹D and M = Σ D'V⁻¹ (y − μ)(y − μ)' V⁻¹ D.", "Working correlation: independence, exchangeable (α from the moment estimator), AR(1).", "QIC = −2Q(β̂) + 2 tr(Ω̂_I V̂_R), as defined by Pan (2001)."],
  assumptions=["Correct mean model and link; independent clusters.", "Missing data completely at random (GEE is not valid under MAR without weighting).", "Enough clusters (about 30 or more) for the sandwich estimator to be reliable."],
  algorithm=["Iteratively reweighted fitting with moment estimates of the scale and α; the sandwich estimator; naive SE reported alongside."],
  limitations=["The AR(1) correlation parameter is estimated by a different moment estimator than the one in statsmodels: with α fixed at the same value the coefficients agree exactly, but with α estimated they can differ (in the binomial benchmark by up to 0.55), so AR(1) results should be read as one valid GEE fit, not as a statsmodels replica.", "statsmodels' QIC omits a weighting of Pan's trace term; the engine follows Pan's definition, so QIC values differ although QICu agrees exactly."],
  refs=["lz86", "pan01"],
  interp=["Coefficients are marginal effects (average over clusters); use the robust SE and its confidence interval, not the naive ones."],
  bench=["statsmodels GEE (coefficients and robust SEs for independence, exchangeable and AR(1) with fixed α; QICu)."], bench_files=["E1", "E2", "E3"])
D("stat_icc", intro="Intraclass correlation coefficients measure agreement or reliability among raters or repeated measurements, in the six forms of Shrout and Fleiss.",
  history="Shrout and Fleiss (1979); confidence intervals following McGraw and Wong (1996).",
  math=["ANOVA mean squares: MS_R (subjects), MS_C (raters), MS_E (error), MS_W (within subjects).", "ICC(1,1) = (MS_R − MS_W)/(MS_R + (k − 1)MS_W); ICC(2,1) = (MS_R − MS_E)/(MS_R + (k − 1)MS_E + k(MS_C − MS_E)/n); ICC(3,1) = (MS_R − MS_E)/(MS_R + (k − 1)MS_E).", "Average-measure forms: ICC(1,k) = (MS_R − MS_W)/MS_R; ICC(2,k) = (MS_R − MS_E)/(MS_R + (MS_C − MS_E)/n); ICC(3,k) = (MS_R − MS_E)/MS_R.", "Confidence intervals by F-distribution formulas of McGraw and Wong; Cronbach's α with the Feldt interval."],
  assumptions=["Subjects are a random sample; raters random (forms 1 and 2) or fixed (form 3).", "Normal errors; complete data (subjects with a missing rating are dropped)."],
  algorithm=["Two-way ANOVA decomposition; closed-form coefficients and intervals; F test of ICC > 0."],
  limitations=["Negative estimates are possible and are reported as computed.", "Choose the form to match the design: using a consistency form for an absolute-agreement question overstates reliability."],
  refs=["sf79", "mw96"],
  interp=["Common labels: below 0.5 poor, 0.5–0.75 moderate, 0.75–0.9 good, above 0.9 excellent (Koo and Li 2016 suggest these cut-offs for the confidence limits, not the point estimate)."],
  bench=["The published Shrout and Fleiss (1979) Table 2 values and pingouin.intraclass_corr (all six forms with confidence intervals)."], bench_files=["E1", "E2", "E3"])
D("stat_bootstrap", intro="The bootstrap estimates the sampling distribution of a statistic by resampling the data, giving standard errors and confidence intervals without a parametric model.",
  history="Efron (1979); the bias-corrected and accelerated (BCa) interval is from Efron (1987).",
  math=["Draw B samples with replacement; θ̂*_b = T(sample_b); SE_boot = sd(θ̂*_b); bias = mean θ̂* − θ̂.", "Percentile interval [q_{α/2}, q_{1−α/2}] of θ̂*; basic interval [2θ̂ − q_{1−α/2}, 2θ̂ − q_{α/2}]; normal interval θ̂ ± z SE_boot.", "BCa: α_1 = Φ(ẑ0 + (ẑ0 + z_α)/(1 − â(ẑ0 + z_α))), ẑ0 = Φ⁻¹(#{θ̂* < θ̂}/B), â = Σ (θ̄_J − θ_(−i))³ / [6 (Σ (θ̄_J − θ_(−i))²)^{3/2}] from the jackknife.", "Two-group statistics are resampled within each group (stratified)."],
  assumptions=["Independent, identically distributed observations (or exchangeable within group).", "A statistic that is a smooth enough functional of the empirical distribution: the bootstrap fails for extreme order statistics."],
  algorithm=["Vectorised resampling in chunks; row-wise statistic evaluation; jackknife for the acceleration; seeded NumPy generator for reproducibility."],
  limitations=["Small samples: percentile intervals undercover (see the simulation); the bootstrap cannot repair a biased or non-representative sample.", "Dependent data (time series, clusters) need a block or cluster bootstrap, which is not included."],
  refs=["efron79", "efron87", "dh97"],
  interp=["Report the BCa interval for skewed statistics; check that the Monte Carlo error from B is small by rerunning with another seed."],
  bench=["scipy.stats.bootstrap (percentile, BCa, basic) at 100,000 resamples within Monte Carlo error, and the closed-form standard error of the mean."], bench_files=["F", "F2"])
D("stat_permutation", intro="Permutation tests obtain the null distribution of a statistic by re-labelling the data in all (or randomly many) exchangeable ways, giving exact or near-exact p-values under minimal assumptions.",
  history="Fisher (1935) and Pitman (1937); Phipson and Smyth (2010) showed how to compute valid p-values from random permutations.",
  math=["For T(x, labels) and M rearrangements: exact p = #{|T*| ≥ |T_obs|}/M_all; Monte Carlo p = (b + 1)/(m + 1), b = #{|T*| ≥ |T_obs|}.", "Tests: difference in means or medians, paired (sign flipping), correlation, one-way F.", "Exact enumeration when the number of rearrangements does not exceed exact_max."],
  assumptions=["Exchangeability of the labels under H0 (this is stronger than equal means: the null is equality of the whole distributions)."],
  algorithm=["Combinatorial enumeration or seeded random permutations; two-sided p by comparing |T|."],
  limitations=["A test of the mean difference with unequal variances is not exact for the equal-means null (see the robustness runs).", "Monte Carlo p-values have sampling error, reported."],
  refs=["fisher35", "ps10"],
  interp=["The exact p-value is the proportion of rearrangements at least as extreme as the data; the reference Welch test is shown for contrast."],
  bench=["scipy.stats.permutation_test and brute-force enumeration for small samples."], bench_files=["F", "F2"])
D("stat_power", intro="Power and sample-size analysis computes the power of a planned test, the sample size required for a target power, or the smallest detectable effect.",
  history="Cohen (1988) systematised effect sizes and power tables.",
  math=["Two-sample t: power = 1 − F_{t'}(t_{1−α/2}; df, δ) + F_{t'}(−t_{1−α/2}; df, δ), δ = d sqrt(n1n2/(n1 + n2)), noncentral t.", "One-way ANOVA: power = 1 − F_{F'}(F_{1−α}; k − 1, N − k, λ), λ = f² N.", "Correlation: Fisher z, power from the normal approximation with z = atanh r sqrt(n − 3) (pwr package convention).", "Two proportions: arcsine transformation with Cohen's h = 2 asin sqrt p1 − 2 asin sqrt p2; χ² goodness-of-fit with noncentrality w² N."],
  assumptions=["The effect size and variability supplied are the truth; power is conditional on them.", "The test's own assumptions hold (normality, equal variances)."],
  algorithm=["Noncentral distribution functions from SciPy; sample size by bracketing and Brent root finding; detectable effect by expanding bracket."],
  limitations=["Analytic approximations only: no simulation-based power for complex designs.", "Post-hoc power computed from the observed effect adds no information beyond the p-value."],
  refs=["cohen88"],
  interp=["Report the effect size assumed and where it came from; plan for a smaller effect than the pilot estimate."],
  bench=["statsmodels.stats.power (t, ANOVA, normal, proportions) and values of the R pwr package; here additionally checked by direct simulation of the same tests (results below)."], bench_files=["F", "F2"])
D("stat_meta_fixed", intro="Fixed-effect (common-effect) meta-analysis pools study effect estimates by inverse-variance weighting under the assumption that all studies estimate one true effect.",
  history="Classical inverse-variance pooling (Hedges and Olkin 1985); Cochran's Q for heterogeneity.",
  math=["θ̂ = Σ w_i y_i / Σ w_i, w_i = 1/v_i; Var θ̂ = 1/Σ w_i; Wald z = θ̂/SE.", "Cochran's Q = Σ w_i (y_i − θ̂)² ~ χ²(k − 1); I² = max(0, (Q − (k − 1))/Q); H² = Q/(k − 1).", "Effect sizes: log risk ratio, log odds ratio and risk difference from counts (0.5 continuity correction when a cell is zero), Hedges' g from means, or supplied estimates with SE or variance."],
  assumptions=["One true effect shared by all studies.", "Within-study variances treated as known.", "Independent studies."],
  algorithm=["Effect-size computation, inverse-variance pooling, heterogeneity statistics, leave-one-out analysis, Egger and Begg small-study tests, forest plot."],
  limitations=["With real between-study heterogeneity the confidence interval is too narrow (see the simulation): use the random-effects model.", "Egger and Begg tests have low power with fewer than about 10 studies and were not cross-checked against another package."],
  refs=["hedges85", "hs02", "egger97", "begg94"],
  interp=["The pooled estimate is the weighted average effect; read Q and I² before relying on it."],
  bench=["statsmodels.stats.meta_analysis.combine_effects (fixed effect) and the BCG vaccine data against metafor."], bench_files=["G"])
D("stat_meta_random", intro="Random-effects meta-analysis allows the true effect to vary between studies and estimates the mean of that distribution, the between-study variance τ² and a prediction interval.",
  history="DerSimonian and Laird (1986); REML and Paule-Mandel estimators of τ² compared by Viechtbauer (2005); the Hartung-Knapp-Sidik-Jonkman interval (Hartung and Knapp 2001).",
  math=["y_i = θ + u_i + e_i, u_i ~ N(0, τ²), e_i ~ N(0, v_i); w_i* = 1/(v_i + τ̂²); θ̂ = Σ w_i* y_i / Σ w_i*.", "τ² estimators: DerSimonian-Laird (Q-moment), Hedges, Paule-Mandel (solves Q(τ²) = k − 1), ML and REML by Fisher scoring.", "Wald interval θ̂ ± z SE, or Hartung-Knapp: θ̂ ± t_{k−1} sqrt(q* / (k − 1)) / sqrt(Σ w*) with q* = Σ w*(y − θ̂)².", "95% prediction interval θ̂ ± t_{k−2} sqrt(τ̂² + SE²); Q-profile confidence interval for τ²."],
  assumptions=["True effects are normally distributed across studies.", "Within-study variances known and correct.", "Independent studies; enough studies (at least 5–10) to estimate τ²."],
  algorithm=["Iterative τ² estimators with bounds and convergence checks; Q-profile root finding; leave-one-out; Egger and Begg tests."],
  limitations=["τ² is imprecise with few studies; the Wald interval undercovers then, and the Hartung-Knapp interval is preferred.", "No meta-regression or multilevel models."],
  refs=["dl86", "viech05", "viech10", "hk01"],
  interp=["Report the pooled effect with its Hartung-Knapp interval, τ², I² and the prediction interval: the latter says what a new study might show."],
  bench=["metafor (rma, REML, HKSJ) published BCG results: pooled −0.7145, SE 0.1798, τ² 0.3132, Q 152.233; DerSimonian-Laird and Paule-Mandel exact against statsmodels."], bench_files=["G"])
